CREATE TABLE IF NOT EXISTS members(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(20) NOT NULL UNIQUE, password VARCHAR(100) NOT NULL, display_name VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS posts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title VARCHAR(200) NOT NULL, body VARCHAR(2000) NOT NULL, author_id BIGINT NOT NULL REFERENCES members(id), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS seed_state(id INT PRIMARY KEY);
